#!/usr/bin/env python3
import sys,urllib.request,json
from pathlib import Path
if len(sys.argv)>1 and sys.argv[1]=='--submit':
    body=Path(sys.argv[2]).read_bytes();print(urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8060/validate',body)).read().decode())
else:
    try:
        body=urllib.request.urlopen('http://127.0.0.1:8088/health').read()
    except urllib.error.HTTPError as e:
        print(e.read().decode());sys.exit(1)
    Path('run').mkdir(exist_ok=True);Path('run/health.ok').write_bytes(body);print(body.decode())

from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
from pathlib import Path
import yaml,json
class H(BaseHTTPRequestHandler):
    def do_GET(self):
        cfg=yaml.safe_load(Path('/testbed/config/local.yaml').read_text()) or {}
        ok=cfg.get('region')=='us-east-1';self.send_response(200 if ok else 503);self.end_headers()
        self.wfile.write(json.dumps({'service':'checkout','status':'ok' if ok else 'unhealthy','region':cfg.get('region')}).encode())
ThreadingHTTPServer(('127.0.0.1',8088),H).serve_forever()

